def city(slot, c):
    name = c["city"]
    secs = [
        (f"SEO and AI search in {name}", "".join(f"<p>{p}</p>" for p in c["intro"])),
        (f"How {name} customers search", "".join(f"<p>{p}</p>" for p in c["search"])),
        (f"How Google ranks local results in {name}", RANK_V[slot % 3] + f"<p>{c['rank']}</p>"),
        (f"Getting recommended by ChatGPT and Google AI in {name}",
         f"<p>{c['ai']}</p><p>Ask these questions in ChatGPT, Gemini, Perplexity and Google each month and record who is named:</p><ol>"
         + "".join(f"<li>{q}</li>" for q in c["prompts"]) + "</ol>"),
        (f"What an SEO plan for a {name} business includes",
         "<table><tr><th>Step</th><th>What it means in practice</th></tr>"
         + "".join(f"<tr><td>{a}</td><td>{b}</td></tr>" for a, b in c["plan"]) + "</table>"),
        (f"Local links and mentions in {name}", f"<p>{c['links_text']}</p>"),
        ("Business Profile basics", "<p>Your Google Business Profile is usually the first thing people see in a local search.</p>" + SAB_V[slot % 3]),
        ("Reviews", f"<p>{c['reviews']}</p>" + REVIEW_V[slot % 3]),
        ("Structured data", "<p>Add LocalBusiness structured data, or the most specific Schema.org type for your business, with your real "
         "name, address, phone, hours and service area, matching your Business Profile exactly. Google's local business documentation "
         "explains how this markup can help it show your details.</p>"),
        (f"City pages that help {name} customers", f"<p>{c['citypage']}</p>" + DOORWAY_V[slot % 3]),
        (f"Industries we often see in {name}",
         f"<p>{c['industries_text']}</p><ul>" + "".join(f"<li><a href=\"{IND[k]['url']}\">{IND[k]['anchor'][:1].upper() + IND[k]['anchor'][1:]}</a></li>" for k in c["industries"]) + "</ul>"),
        ("How to choose an SEO company", "<ul>" + "".join(f"<li>{q}</li>" for q in c["choose"]) + "</ul>"),
        (f"Working with Chimera from Anaheim", f"<p>{c['from_anaheim']}</p>"),
        (f"Where the opportunity is in {name}", f"<p>{c['opportunity']}</p>"),
        ("The short version", f"<p>{c['short']}</p>"),
    ]
    faqs = c["faqs"] + [
        (f"Does Chimera work with businesses in {name}?", f"Yes. Chimera is based in Anaheim and works with businesses in {name} and across Orange County, California."),
        ("Can you guarantee first place on Google?", "No honest agency can. Google says there is no way to request or pay for a better local ranking; good work improves your chances."),
    ]
    return page(c["slug"], c["query"], c["kw"], f"Local SEO · {name}", c["title"], c["meta"], c["h1"], c["answer"], c["takeaways"],
                secs, faqs, [IND[k] for k in c["industries"][:2]] + [LOCALSEO, GBP, OCAGENCY, CHATGPT_LOCAL, AUD],
                ["g_rank", "g_gbp", "g_fake", "spam", "g_local", c["wiki"], "w_oc"],
                [local_rank_flow(2), oc_cities(5, title=f"{name} among Orange County's largest cities", highlight=name),
                 V.timeline(12, f"A first 90 days for a {name} business", "What the first three months usually look like.",
                            [("Weeks 1-2", "Audit", "Profile, listings, site and AI answers."), ("Weeks 3-6", "Fix", "Profile, structured data, service pages."),
                             ("Weeks 7-10", "Publish", "Answer pages and local proof."), ("Weeks 11-13", "Measure", "Calls, rankings and AI mentions.")])],
                secondary=c["secondary"], hero_query=c["hero"], short_title=c["short_title"])


